    /// <summary><c>darken</c>：逐通道取上下两层中较暗的值，结果不会比任何一层更亮。</summary>
    public static readonly CssValue Darken = "darken";

    /// <summary><c>difference</c>：取上下两层颜色差的绝对值；与白色混合会反相，与黑色混合则不变。</summary>
