/// <summary><c>place-content</c> 的关键字取值；类型与 <see cref="Style.PlaceContent"/> 一致，可直接赋值。</summary>
public static class PlaceContent
{
    /// <summary><c>baseline</c>：按首行文字的基线与同组其他项对齐；单独使用等同 <c>first baseline</c>。</summary>
