    public static readonly CssValue End = "end";

    /// <summary><c>first</c>：与 <c>baseline</c> 搭配（<c>first baseline</c>）：以第一行文字的基线对齐，单写 <c>baseline</c> 与其等效。</summary>
    public static readonly CssValue First = "first";

